import React, { Component, Fragment } from "react";
import {
  Collapse,
  Navbar,
  NavbarToggler,
  NavbarBrand,
  Nav,
  NavLink,
  UncontrolledDropdown,
  DropdownToggle,
  DropdownMenu,
  DropdownItem
} from "reactstrap";
import { connect } from "react-redux";
import RegisterModal from "./auth/RegisterModal";
import Logout from "./auth/Logout";
import LoginModal from "./auth/LoginModal";
import PropTypes from "prop-types";
import { changePage } from "../actions/pageActions";
import ArrowForwardIcon from "@material-ui/icons/ArrowForward";
import ArrowBackIcon from "@material-ui/icons/ArrowBack";
import store from "../store";
import { loadUser } from "../actions/authActions";
class AppNavbar extends Component {
  state = {
    isOpen: false
  };
  componentDidUpdate() {
    //store.dispatch(loadUser()); ///using this to load users after logging in/registering.  Need to move this to actions or something
  }
  static propTypes = {
    auth: PropTypes.object.isRequired,
    changePage: PropTypes.func.isRequired
  };
  toggle = () => {
    this.setState({
      isOpen: !this.state.isOpen
    });
  };
  onPageChangeClick = (navType, page) => {
    const pageDetail = {
      navType,
      page
    };
    this.props.changePage(pageDetail);
  };

  render() {
    const { isAuthenticated, user } = this.props.auth;
    const authLinks = (
      <Fragment>
        <Logout />
      </Fragment>
    );
    const guestLinks = (
      <Fragment>
        <RegisterModal />
        {/*<LoginModal />*/}
      </Fragment>
    );
    return (
      <div>
        <Navbar fixed="top" color="dark" dark expand="sm" className="mb-5">
          <NavbarBrand href="/">Struct</NavbarBrand>
          <Nav className="mr-auto" navbar>
            {this.props.auth.user.userAccess.access.COA_1_V ? (
              <NavLink
                className="navbar-text"
                onClick={this.onPageChangeClick.bind(
                  this,
                  "MainNav",
                  "Clients"
                )}
              >
                Clients
              </NavLink>
            ) : (
              ""
            )}

            {this.props.auth.user.userAccess.access.PGOA_1_V ? (
              <NavLink
                className="navbar-text"
                onClick={this.onPageChangeClick.bind(
                  this,
                  "MainNav",
                  "ProcessGroups"
                )}
              >
                Process Groups
              </NavLink>
            ) : (
              ""
            )}

            {this.props.auth.user.userAccess.access.IOA_1_V ? (
              <NavLink
                className="navbar-text"
                onClick={this.onPageChangeClick.bind(this, "MainNav", "Items")}
              >
                Items
              </NavLink>
            ) : (
              ""
            )}
          </Nav>
          <NavbarToggler onClick={this.toggle} />

          <Collapse isOpen={this.state.isOpen} navbar>
            <Nav className="ml-auto " navbar>
              <NavLink className="navbar-text mt-2">
                <ArrowBackIcon />
              </NavLink>
              <NavLink className="navbar-text mt-2 mr-2">
                <ArrowForwardIcon />
              </NavLink>
              <NavLink className="navbar-text mt-2 mr-2 disabled">|</NavLink>

              {this.props.auth.user.userAccess.access.OA_2_V ? (
                <div>
                  <NavLink
                    className="navbar-text mt-2 mr-1"
                    onClick={this.onPageChangeClick.bind(
                      this,
                      "OpsNav",
                      "ConfigurationHistory"
                    )}
                  >
                    Configuration History
                  </NavLink>
                  <NavLink className="navbar-text mt-2 mr-1 disabled">
                    |
                  </NavLink>
                </div>
              ) : (
                ""
              )}

              <UncontrolledDropdown nav inNavbar className="navbar-text">
                <DropdownToggle nav caret>
                  {isAuthenticated
                    ? `Logged in as: ${user.name}`
                    : "Not logged in"}
                </DropdownToggle>

                <DropdownMenu>
                  {this.props.auth.user.userAccess.access.OA_1_V ? (
                    <DropdownItem
                      onClick={this.onPageChangeClick.bind(
                        this,
                        "OpsNav",
                        "AccessSetup"
                      )}
                    >
                      Access Setup
                    </DropdownItem>
                  ) : (
                    ""
                  )}

                  <DropdownItem
                    onClick={this.onPageChangeClick.bind(
                      this,
                      "OpsNav",
                      "ViewAccess"
                    )}
                  >
                    View Access
                  </DropdownItem>
                  <DropdownItem divider />
                  {isAuthenticated ? authLinks : guestLinks}
                </DropdownMenu>
              </UncontrolledDropdown>
            </Nav>
          </Collapse>
        </Navbar>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  //this method is used to get a portion of the overall app state to use in this component
  auth: state.auth
});
export default connect(mapStateToProps, { changePage })(AppNavbar);
//export default connect(mapStateToProps, { getItems, deleteItem })(ShoppingList);
